appearances.css:
.app{display:flex;flex-wrap:wrap;gap:3px 5px;align-items:center;padding:6px;font-size:9px}
.row,.view{display:contents}
.row label,.view label{display:inline-flex;gap:2px;align-items:center;font-size:9px}
select,button{font-size:9px;padding:2px 4px;border-radius:3px}
input[type=checkbox]{margin:0;width:12px;height:12px}
.line{display:inline-flex;gap:5px;justify-content:flex-start;align-items:center;font-size:9px}
.line>span{white-space:nowrap}
.kn{width:26px!important;height:26px!important}
.kn svg{width:100%;height:100%}
.eqs,.grid,.proposal,pre,.screen,.status{flex:1 1 100%;min-width:0}
.eqs{gap:3px;overflow:visible!important}
.sec{flex:1 1 calc(var(--n)*26px + 6px)!important;min-width:calc(var(--n)*25px + 6px)!important;padding:3px 3px 4px;border-radius:3px}
h3{font-size:8px;margin:0 0 2px;letter-spacing:.06em}
h3 small{font-size:8px}
.cells{gap:0;justify-content:space-between}
.cell{flex:1 1 25px;min-width:25px;max-width:46px;gap:0;justify-items:center}
.cell .kn,.control .kn{justify-self:center!important}
.cell .kn{order:1}
.cell output.val{order:2;font-size:8px;min-height:0;line-height:1.1;letter-spacing:-.04em}
.cell .num{order:3;min-width:16px;height:14px;font-size:9px;padding:0 2px;margin-top:1px}
.grid{display:flex;flex-wrap:wrap;gap:3px}
.control{flex:1 1 0;min-width:0;padding:3px 4px;display:grid;justify-items:center;gap:0;border-radius:3px}
.control .line{display:contents}
.control .kn{order:1}
.control output{order:2;font-size:8px;line-height:1.1;white-space:nowrap}
.control .line>span{order:3;font-size:8px;text-align:center;line-height:1.1;white-space:normal}
.control .lock{order:4;font-size:8px;display:inline-flex;gap:2px;align-items:center}
.control .lock input{width:12px;height:12px}
.control:has(.line>input[type=checkbox]){grid-auto-flow:column;justify-content:center;align-content:center;gap:4px}
.control:has(.line>input[type=checkbox]) .line{display:contents}
.control:has(.line>input[type=checkbox]) .line>span{order:0;font-size:9px}
pre{padding:3px 6px;font-size:8.5px;line-height:1.35}
.screen{height:44px}
.status,.proposal{font-size:9px;line-height:1.3}
.proposal{padding:3px 5px}
.eqs[data-layout=side]{flex-wrap:wrap}
.eqs[data-layout=stack]{flex-direction:column}
.eqs[data-layout=stack] .sec{flex:none!important;min-width:0!important}
.eqs[data-layout=stack] .cells{justify-content:flex-start;gap:2px}
